package app;

import app.repositories.MemoryAuditLogRepository;
import app.repositories.MemoryCategoryRepository;
import app.repositories.MemoryCustomerRepository;
import app.repositories.MemoryOrderLineRepository;
import app.repositories.MemoryOrderRepository;
import app.repositories.MemoryProductRepository;
import app.repositories.MemoryProductTagRepository;
import app.repositories.MemoryTagRepository;
import app.repositories.SqlAuditLogRepository;
import app.repositories.SqlCategoryRepository;
import app.repositories.SqlCustomerRepository;
import app.repositories.SqlOrderLineRepository;
import app.repositories.SqlOrderRepository;
import app.repositories.SqlProductRepository;
import app.repositories.SqlProductTagRepository;
import app.repositories.SqlTagRepository;
import java.util.function.Function;

/** The in-memory repositories, for tests and for trying the services without a database. */
public class MemoryUnitOfWork implements UnitOfWork {
    private final SqlCustomerRepository customers = new MemoryCustomerRepository();
    private final SqlCategoryRepository categories = new MemoryCategoryRepository();
    private final SqlProductRepository products = new MemoryProductRepository();
    private final SqlOrderRepository orders = new MemoryOrderRepository();
    private final SqlOrderLineRepository orderLines = new MemoryOrderLineRepository();
    private final SqlTagRepository tags = new MemoryTagRepository();
    private final SqlProductTagRepository productTags = new MemoryProductTagRepository();
    private final SqlAuditLogRepository auditLog = new MemoryAuditLogRepository();

    @Override
    public SqlCustomerRepository customers() {
        return customers;
    }

    @Override
    public SqlCategoryRepository categories() {
        return categories;
    }

    @Override
    public SqlProductRepository products() {
        return products;
    }

    @Override
    public SqlOrderRepository orders() {
        return orders;
    }

    @Override
    public SqlOrderLineRepository orderLines() {
        return orderLines;
    }

    @Override
    public SqlTagRepository tags() {
        return tags;
    }

    @Override
    public SqlProductTagRepository productTags() {
        return productTags;
    }

    @Override
    public SqlAuditLogRepository auditLog() {
        return auditLog;
    }

    /** Memory has no transactions: changes are kept as they are made. */
    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        return work.apply(this);
    }
}

