package app;

import app.repositories.SqlAuditLogRepository;
import app.repositories.SqlCategoryRepository;
import app.repositories.SqlCustomerRepository;
import app.repositories.SqlOrderLineRepository;
import app.repositories.SqlOrderRepository;
import app.repositories.SqlProductRepository;
import app.repositories.SqlProductTagRepository;
import app.repositories.SqlTagRepository;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.function.Function;

/** The repositories over one JDBC connection, and its transaction. */
public class SqlUnitOfWork implements UnitOfWork {
    private final Connection connection;
    private final SqlCustomerRepository customers;
    private final SqlCategoryRepository categories;
    private final SqlProductRepository products;
    private final SqlOrderRepository orders;
    private final SqlOrderLineRepository orderLines;
    private final SqlTagRepository tags;
    private final SqlProductTagRepository productTags;
    private final SqlAuditLogRepository auditLog;

    public SqlUnitOfWork(Connection connection) {
        this.connection = connection;
        this.customers = new SqlCustomerRepository(connection);
        this.categories = new SqlCategoryRepository(connection);
        this.products = new SqlProductRepository(connection);
        this.orders = new SqlOrderRepository(connection);
        this.orderLines = new SqlOrderLineRepository(connection);
        this.tags = new SqlTagRepository(connection);
        this.productTags = new SqlProductTagRepository(connection);
        this.auditLog = new SqlAuditLogRepository(connection);
    }

    public Connection connection() {
        return connection;
    }

    @Override
    public SqlCustomerRepository customers() {
        return customers;
    }

    @Override
    public SqlCategoryRepository categories() {
        return categories;
    }

    @Override
    public SqlProductRepository products() {
        return products;
    }

    @Override
    public SqlOrderRepository orders() {
        return orders;
    }

    @Override
    public SqlOrderLineRepository orderLines() {
        return orderLines;
    }

    @Override
    public SqlTagRepository tags() {
        return tags;
    }

    @Override
    public SqlProductTagRepository productTags() {
        return productTags;
    }

    @Override
    public SqlAuditLogRepository auditLog() {
        return auditLog;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        try {
            // Joins the transaction already open
            if (!connection.getAutoCommit()) return work.apply(this);
            connection.setAutoCommit(false);
            try {
                T result = work.apply(this);
                connection.commit();
                return result;
            } catch (RuntimeException error) {
                connection.rollback();
                throw error;
            } finally {
                connection.setAutoCommit(true);
            }
        } catch (SQLException error) {
            throw Sql.failure(error);
        }
    }
}

