        super(entity + ": " + reason);
        this.entity = entity;
        this.reason = reason;
        this.fields = List.copyOf(fields);
    }

    public ConflictException(String entity, String reason) {
        this(entity, reason, List.of());
    }

    public String getEntity() {
        return entity;
